import{z as l,x as n,o as E,c as p,q as B,j as i,D as e,d as t,s as o,S as A,b as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"Spectre 缓解与代价","description":"","frontmatter":{"title":"Spectre 缓解与代价","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/spectre-mitigations.md","filePath":"cs/spectre-mitigations.md","lastUpdated":1791063341000}'),c={name:"cs/spectre-mitigations.md"};function d(m,a,h,C,f,u){const s=n("Mermaid");return E(),p("div",null,[a[2]||(a[2]=B('<h1 id="spectre-缓解与代价" tabindex="-1">Spectre 缓解与代价 <a class="header-anchor" href="#spectre-缓解与代价" aria-label="Permalink to &quot;Spectre 缓解与代价&quot;">​</a></h1><div class="epigraph"><p>Spectre 用预测执行把秘密打进微结构状态。缓解是隔离、栅栏、间接预测限制——每一刀都有性能账。合同是威胁模型与账单，不是「已彻底消失」。</p><footer>—— Kocher et al., Spectre Attacks, 2019 IEEE S&amp;P；对照[瞬态执行](/cs/transient-exec)</footer></div><p>上一课<a href="/cs/puf">PUF</a>讲制造差异当身份；缺口回到<strong>共享 CPU</strong>：主干瞬态执行课已给出现象，本课收拢缓解手段与它们的性能代价，不给测量密钥的步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>操作系统的进程隔离只管架构状态——寄存器与内存页，不管预测器与缓存这类微结构状态：错误路径上的加载照样把秘密带进缓存。缓解清单分层：软件侧 retpoline 重写间接跳转、编译器插栅栏斩断泄漏窗口；硬件侧 IBRS 一类微码开关限制间接预测跨权限共享；系统侧站点隔离把不同站点拆进不同进程、云上减少共驻。缺口是性能与覆盖的账。</p><h3 id="浏览器" tabindex="-1">浏览器 <a class="header-anchor" href="#浏览器" aria-label="Permalink to &quot;浏览器&quot;">​</a></h3><p>浏览器值得单说：站点隔离是纯软件缓解，不改一条 CPU 指令，但把「能共享受害者地址空间的对手」压到同站点之内；它与微码缓解叠加，各挡各的变体。</p><p><span class="marginnote">直觉类比：站点隔离像把不同租户从合租的大开间搬进各自独立的房间——CPU 一颗没换，只是再没人能和你共用厨房（地址空间），偷看你灶台的机会随之消失。</span></p><p><span class="marginnote">Kocher et al. Spectre。禁止利用步骤。Rowhammer 下一课是 DRAM 物理。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是把软件缓解与硬件缓解对照记账：栅栏与 retpoline 在热路径上直接加指令；页表隔离把内核页从用户态摘掉，系统调用与上下文切换变贵；微码开关关掉的是积累几十年的预测器收益。每项缓解都要问覆盖率——封哪几个变体，残余多大。下一课 Rowhammer。</p><p><span class="marginnote">术语翻译：retpoline 就是把间接跳转改写成一段「永远返回到正确地方」的固定指令序列，让被污染的分支目标预测器派不上用场。代价是这条路径的预测收益与前端效率全部作废——这正是它在热路径上有账可记的原因。</span></p>',13)),(E(),i(A,null,{default:e(()=>[o(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20SPEC%5B%22%E9%A2%84%E6%B5%8B%E6%89%A7%E8%A1%8C%22%5D%20--%3E%20LEAK%5B%22%E5%BE%AE%E7%BB%93%E6%9E%84%E7%8A%B6%E6%80%81%22%5D%0A%20%20MIT%5B%22%E6%A0%85%E6%A0%8F%E4%B8%8E%E9%9A%94%E7%A6%BB%22%5D%20--%3E%20COST%5B%22%E6%80%A7%E8%83%BD%E8%B4%A6%22%5D%0A%20%20MIT%20--%3E%20RES%5B%22%E6%AE%8B%E5%B7%AE%E4%BB%8D%E8%A6%81%E6%A8%A1%E5%9E%8B%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"机制最反直觉的一层：程序在架构上完全正确——每条指令的提交结果都对——秘密仍从瞬态路径漏出，因为微结构状态不随错误路径回滚。这把「正确」与「不泄漏」拆成两个合同：单元测试能过，侧信道仍在。缓解因此永远带残差，要靠建模特跟踪新变体。Rowhammer 下一课扰的是 DRAM 比特而不是预测器。",-1)),(E(),i(A,null,{default:e(()=>[o(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20I%5B%22%E6%8C%87%E4%BB%A4%E6%B5%81%E5%90%AB%E8%AF%AF%E9%A2%84%E6%B5%8B%E5%88%86%E6%94%AF%22%5D%20--%3E%20EX%5B%22%E9%94%99%E8%AF%AF%E8%B7%AF%E5%BE%84%20load%20%E6%8E%A2%E7%B4%A2%E6%80%A7%E5%9C%B0%E6%89%A7%E8%A1%8C%22%5D%0A%20%20EX%20--%3E%20ARCH%5B%22%E6%9E%B6%E6%9E%84%E5%B1%82%EF%BC%9A%E7%BB%93%E6%9E%9C%E4%B8%8D%E6%8F%90%E4%BA%A4%EF%BC%8C%E6%B5%8B%E8%AF%95%E5%85%A8%E8%BF%87%22%5D%0A%20%20EX%20--%3E%20MICRO%5B%22%E5%BE%AE%E7%BB%93%E6%9E%84%E5%B1%82%EF%BC%9Acache%20%E8%A2%AB%E6%B1%A1%E6%9F%93%22%5D%0A%20%20MICRO%20--%3E%20T%5B%22%E6%94%BB%E5%87%BB%E8%80%85%E7%94%A8%E6%97%B6%E5%BA%8F%E5%B7%AE%E8%AF%BB%E5%87%BA%E6%B1%A1%E6%9F%93%22%5D%0A%20%20T%20--%3E%20FIX%5B%22%E7%BC%93%E8%A7%A3%EF%BC%9A%E6%A0%85%E6%A0%8F%20%2F%20%E9%9A%94%E7%A6%BB%EF%BC%8C%E5%90%84%E5%B8%A6%E6%80%A7%E8%83%BD%E7%A8%8E%22%5D%0A%20%20FIX%20--%3E%20RES%5B%22%E6%AE%8B%E5%B7%AE%E4%BB%8D%E9%9C%80%E5%BB%BA%E6%A8%A1%E8%B7%9F%E8%B8%AA%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=B('<p>这张图回答的是：泄漏发生在哪一层——架构层与微结构层在误预测处分岔，「正确」与「不泄漏」从这一分岔起成为两份独立合同，缓解只能堵微结构那一条支路。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写 PoC；边界要点名：缓解矩阵随硬件代际变化，同一微码开关在不同 CPU 上语义不同，安全声明必须绑定具体型号与微码版本。Rowhammer 缓解下一课。</p><p><span class="marginnote">常见误区：初学者容易以为打上补丁就「修好了」。每项缓解只封特定变体，残余风险要靠持续的侧信道建模跟踪；这一步若做错——把「有补丁」当成「已关闭」——威胁模型就会系统性偏乐观。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PUF 之后回到共享 CPU 泄漏。</li><li>缓解是隔离加栅栏，带性能账。</li><li>不是一次补丁永久关闭。</li><li>下一课 Rowhammer。</li><li>出处：Kocher et al., Spectre；<a href="/cs/transient-exec">transient-exec</a>。</li></ul>',6))])}const D=l(c,[["render",d]]);export{_ as __pageData,D as default};
